 import {
   deleteComment,
   favoriteArticle,
+  getCommentsByArticle,
   unfavoriteArticle,
+  updateComment,
 } from '../../app/routes/article/article.service';

 describe('ArticleService', () => {
+  describe('updateComment', () => {
+    test('should update the body, set updatedAt and return the comment', async () => {
+      // Given
+      const slug = 'How-to-train-your-dragon';
+      const commentId = 123;
+      const userId = 456;
+      const newBody = 'An edited comment';
+
+      const mockedUpdatedComment = {
+        id: commentId,
+        createdAt: new Date('2026-01-01T10:00:00Z'),
+        updatedAt: new Date('2026-01-01T11:00:00Z'),
+        body: newBody,
+        authorId: userId,
+        articleId: 789,
+        author: {
+          username: 'RealWorld',
+          bio: null,
+          image: null,
+          followedBy: [{ id: 111 }],
+        },
+      };
+
+      // When
+      // @ts-ignore
+      prismaMock.comment.findFirst.mockResolvedValue({ author: { id: userId } });
+      // @ts-ignore
+      prismaMock.comment.update.mockResolvedValue(mockedUpdatedComment);
+
+      // Then
+      await expect(updateComment(newBody, slug, commentId, userId)).resolves.toEqual({
+        id: commentId,
+        createdAt: mockedUpdatedComment.createdAt,
+        updatedAt: mockedUpdatedComment.updatedAt,
+        body: newBody,
+        author: {
+          username: 'RealWorld',
+          bio: null,
+          image: null,
+          following: false,
+        },
+      });
+      expect(prismaMock.comment.update).toHaveBeenCalledWith(
+        expect.objectContaining({
+          where: { id: commentId },
+          data: expect.objectContaining({ body: newBody, updatedAt: expect.any(Date) }),
+        }),
+      );
+    });
+
+    test('should throw a 422 if the body is blank', async () => {
+      // Then
+      await expect(
+        updateComment('', 'How-to-train-your-dragon', 123, 456),
+      ).rejects.toMatchObject({
+        errorCode: 422,
+        message: { errors: { body: ["can't be blank"] } },
+      });
+    });
+
+    test('should throw a 404 if the comment is not found on the article', async () => {
+      // When
+      // @ts-ignore
+      prismaMock.comment.findFirst.mockResolvedValue(null);
+
+      // Then
+      await expect(
+        updateComment('edited', 'How-to-train-your-dragon', 123, 456),
+      ).rejects.toMatchObject({ errorCode: 404 });
+      expect(prismaMock.comment.update).not.toHaveBeenCalled();
+    });
+
+    test('should throw a 404 for a soft-deleted comment and only look up live rows', async () => {
+      // When
+      // @ts-ignore
+      prismaMock.comment.findFirst.mockResolvedValue(null);
+
+      // Then
+      await expect(
+        updateComment('edited', 'How-to-train-your-dragon', 123, 456),
+      ).rejects.toMatchObject({ errorCode: 404 });
+      expect(prismaMock.comment.findFirst).toHaveBeenCalledWith(
+        expect.objectContaining({
+          where: expect.objectContaining({ id: 123, deletedAt: null }),
+        }),
+      );
+      expect(prismaMock.comment.update).not.toHaveBeenCalled();
+    });
+
+    test('should throw a 403 if the user is not the author', async () => {
+      // When
+      // @ts-ignore
+      prismaMock.comment.findFirst.mockResolvedValue({ author: { id: 999 } });
+
+      // Then
+      await expect(
+        updateComment('edited', 'How-to-train-your-dragon', 123, 456),
+      ).rejects.toMatchObject({ errorCode: 403 });
+      expect(prismaMock.comment.update).not.toHaveBeenCalled();
+    });
+  });
+
   describe('deleteComment', () => {
-    test('should throw an error ', () => {
+    test('should soft delete the comment by setting deletedAt and keep the row', async () => {
       // Given
-      const id = 123;
-      const idUser = 456;
+      const commentId = 123;
+      const userId = 456;
+
+      // When
+      // @ts-ignore
+      prismaMock.comment.findFirst.mockResolvedValue({
+        author: { id: userId, username: 'RealWorld' },
+      });
+      // @ts-ignore
+      prismaMock.comment.update.mockResolvedValue({});
+
+      // Then
+      await expect(deleteComment(commentId, userId)).resolves.toBeUndefined();
+      expect(prismaMock.comment.update).toHaveBeenCalledWith({
+        where: { id: commentId },
+        data: { deletedAt: expect.any(Date) },
+      });
+      expect(prismaMock.comment.delete).not.toHaveBeenCalled();
+    });
+
+    test('should throw a 404 and not update if no live comment of the user matches', async () => {
+      // Given
+      const commentId = 123;
+      const userId = 456;

       // When
       // @ts-ignore
       prismaMock.comment.findFirst.mockResolvedValue(null);

       // Then
-      expect(deleteComment(id, idUser)).rejects.toThrowError();
+      await expect(deleteComment(commentId, userId)).rejects.toMatchObject({ errorCode: 404 });
+      expect(prismaMock.comment.findFirst).toHaveBeenCalledWith(
+        expect.objectContaining({
+          where: expect.objectContaining({
+            id: commentId,
+            deletedAt: null,
+            author: { id: userId },
+          }),
+        }),
+      );
+      expect(prismaMock.comment.update).not.toHaveBeenCalled();
+    });
+
+    test('should throw a 403 if the comment belongs to another author', async () => {
+      // When
+      // @ts-ignore
+      prismaMock.comment.findFirst.mockResolvedValue({
+        author: { id: 999, username: 'Other' },
+      });
+
+      // Then
+      await expect(deleteComment(123, 456)).rejects.toMatchObject({ errorCode: 403 });
+      expect(prismaMock.comment.update).not.toHaveBeenCalled();
+    });
+  });
+
+  describe('getCommentsByArticle', () => {
+    test('should only ask for comments that are not soft-deleted', async () => {
+      // Given
+      const slug = 'How-to-train-your-dragon';
+
