+      // @ts-ignore
+      prismaMock.article.findUnique.mockResolvedValue({ comments: [] });
+
+      // Then
+      await expect(getCommentsByArticle(slug)).resolves.toEqual([]);
+      expect(prismaMock.article.findUnique).toHaveBeenCalledWith(
+        expect.objectContaining({
+          include: {
+            comments: expect.objectContaining({
+              where: expect.objectContaining({ deletedAt: null }),
+            }),
+          },
+        }),
+      );
+    });
+
+    test('should map the returned comments to the list shape', async () => {
+      // Given
+      const slug = 'How-to-train-your-dragon';
+      const userId = 456;
+      const createdAt = new Date('2026-01-01T10:00:00Z');
+      const updatedAt = new Date('2026-01-01T10:00:00Z');
+
+      // When
+      // @ts-ignore
+      prismaMock.article.findUnique.mockResolvedValue({
+        comments: [
+          {
+            id: 123,
+            createdAt,
+            updatedAt,
+            body: 'A live comment',
+            author: {
+              username: 'RealWorld',
+              bio: null,
+              image: null,
+              followedBy: [{ id: userId }],
+            },
+          },
+        ],
+      });
+
+      // Then
+      await expect(getCommentsByArticle(slug, userId)).resolves.toEqual([
+        {
+          id: 123,
+          createdAt,
+          updatedAt,
+          body: 'A live comment',
+          author: {
+            username: 'RealWorld',
+            bio: null,
+            image: null,
+            following: true,
+          },
+        },
+      ]);
     });
   });

